#requires -Version 5.1
<#
SRE October 31 consolidated read-only collection. No network calls or replay execution. Captures current replay evidence and runtime inventory. No administrator rights or new software.
Close SRE before running. This script never starts/stops SRE or opens original
databases through SQLite. It locks originals for reading, copies DB + WAL/journal,
and uses Windows' built-in SQLite backup API ONLY on those private copies.
Upload only the ZIP printed after SUCCESS. A failure produces no accepted ZIP.
#>
[CmdletBinding()]
param(
    [string]$AppDataRoot = (Join-Path $env:LOCALAPPDATA 'StockRecommendationEngine'),
    [string]$EngineRoot = '',
    [string]$OutputDirectory = '',
    [switch]$SkipOfficialDownloads
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

function Get-SreHash([string]$Path) {
    # FileShare.Read also works while the collector holds a read-only DB lock.
    $stream = [IO.File]::Open($Path, 'Open', 'Read', 'Read')
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($stream))).Replace('-', '').ToLowerInvariant() }
    finally { $sha.Dispose(); $stream.Dispose() }
}
function Test-SreInside([string]$Path, [string]$Parent) {
    return $Path.Equals($Parent, [StringComparison]::OrdinalIgnoreCase) -or
        $Path.StartsWith($Parent.TrimEnd('\','/') + [IO.Path]::DirectorySeparatorChar, [StringComparison]::OrdinalIgnoreCase)
}
function Test-SreSqliteFile([string]$Path) {
    if ($Path -match '(?i)\.(sqlite|sqlite3|db|db3)$') { return $true }
    if ($Path -match '(?i)-(wal|shm|journal)$') { return $false }
    $stream=[IO.File]::Open($Path,'Open','Read','Read')
    try {
        if ($stream.Length -lt 16) { return $false }
        $header=New-Object byte[] 16
        [void]$stream.Read($header,0,16)
        return [Text.Encoding]::ASCII.GetString($header) -ceq "SQLite format 3`0"
    } finally { $stream.Dispose() }
}
function Assert-SreStopped([string]$DataRoot, [string]$InstallRoot) {
    # Parse Windows argv and expand hybrid long/8.3 directory aliases before matching.
    if(-not ('SreContinuityProcessPaths' -as [type])) {
        Add-Type -TypeDefinition @'
using System;
using System.IO;
using System.Text;
using System.Runtime.InteropServices;
public static class SreContinuityProcessPaths {
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode)] static extern uint GetLongPathName(string path,StringBuilder output,uint size);
 [DllImport("shell32.dll",CharSet=CharSet.Unicode)] static extern IntPtr CommandLineToArgvW(string command,out int count);
 [DllImport("kernel32.dll")] static extern IntPtr LocalFree(IntPtr p);
 static string Long(string p) {var b=new StringBuilder(32768);return GetLongPathName(p,b,32768)>0?b.ToString():Path.GetFullPath(p);}
 public static bool References(string command,string root) {
  if(String.IsNullOrEmpty(command))return false;
  int count;IntPtr p=CommandLineToArgvW(command,out count);if(p==IntPtr.Zero)return false;
  try {string target=Long(root).TrimEnd('\\','/');for(int i=0;i<count;i++) {
   string arg=Marshal.PtrToStringUni(Marshal.ReadIntPtr(p,i*IntPtr.Size));
   if(!Directory.Exists(arg)&&!File.Exists(arg))continue;
   string path=Long(arg);if(path.Equals(target,StringComparison.OrdinalIgnoreCase)||path.StartsWith(target+"\\",StringComparison.OrdinalIgnoreCase))return true;
  }return false;}finally{LocalFree(p);}
 }
}
'@
    }
    # Fail closed if process inventory cannot be read. Never terminate a process.
    $aliases=@($InstallRoot,$DataRoot)
    $fso=New-Object -ComObject Scripting.FileSystemObject
    try { foreach($r in @($InstallRoot,$DataRoot)) { $f=$fso.GetFolder($r); try { $aliases+=@([string]$f.ShortPath,[string]$f.Path) } finally { [void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($f) } } }
    finally { [void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($fso) }
    $processes = @(Get-CimInstance Win32_Process -ErrorAction Stop)
    foreach ($p in $processes) {
        if ($p.ProcessId -eq $PID) { continue }
        $name = [string]$p.Name
        $exe = [string]$p.ExecutablePath
        $cmd = [string]$p.CommandLine
        $isShell = $name -match '^(powershell|pwsh|cmd|conhost)\.exe$'
        $inInstall = $exe -and ((Test-SreInside $exe $InstallRoot) -or (Test-SreInside $exe $DataRoot))
        $namedApp = $name -match '^(StockRecommendationEngine|stock-recommendation-engine|stock_app_launcher|stock_app_ops_launcher|sre)\.exe$'
        $backend = $name -match '^(python[^\/ ]*|uvicorn)(\.exe)?$' -and
            ($cmd -match '(run_modern_ui|stock_app_launcher|stock_app_ops_launcher|modern_ui[./\\:]|uvicorn.+modern_ui)' -or
             (@($aliases | Where-Object { $cmd -and $cmd.Replace('/','\').IndexOf($_.Replace('/','\'),[StringComparison]::OrdinalIgnoreCase) -ge 0 }).Count -gt 0))
        if (($inInstall -and -not $isShell) -or $namedApp -or $backend -or ($name -match "^python" -and [SreContinuityProcessPaths]::References($cmd,$InstallRoot))) {
            throw "SRE appears to be running (PID $($p.ProcessId), $name). Close SRE and rerun this script. No process was stopped."
        }
    }
}
function Get-SreFiles([string]$Root, [string]$Label, [string]$SkipRoot, $Excluded) {
    $pending = New-Object 'Collections.Generic.Stack[string]'
    $pending.Push($Root)
    while ($pending.Count) {
        $folder = $pending.Pop()
        foreach ($item in Get-ChildItem -LiteralPath $folder -Force -ErrorAction Stop) {
            $relative = $item.FullName.Substring($Root.Length).TrimStart('\','/')
            if ($SkipRoot -and (Test-SreInside $item.FullName $SkipRoot)) { continue }
            $why = $null
            if ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) { $why = 'REPARSE_POINT_NOT_FOLLOWED' }
            elseif ($item.PSIsContainer -and $item.Name -match '^(\.git|\.venv|venv|env|node_modules|__pycache__|\.pytest_cache|\.mypy_cache|site-packages|\.tox|\.ruff_cache|\.build|build|dist|target)$') { $why = 'DEPENDENCY_OR_BUILD_DIRECTORY' }
            elseif ($item.PSIsContainer -and $item.Name -match '^(\.replay-v10-deps|\.replay-v10-final-deps)$') { $why = 'PRIVATE_BINARY_RUNTIME_RECORDED_SEPARATELY' }
            elseif ($Label -eq 'application-state' -and $item.PSIsContainer -and $item.Name -match '^native-engine-') { $why = 'OTHER_INSTALLED_ENGINE_VERSION' }
            elseif ($item.PSIsContainer -and $item.Name -match '(?i)(^v10[-_].*runtime$|^runtime[-_]?v10$|^private[-_]runtime$|^replay[-_](feature|input)[-_]cache|^historical_replay_(feature|input)_cache|^replay_v10_(features|cache))') { $why = 'PRIVATE_RUNTIME_OR_REPLAY_FEATURE_CACHE' }
            elseif (-not $item.PSIsContainer -and $item.Name -match '(?i)^(\.env($|\.)|credentials?($|\.)|secrets?($|\.)|tokens?($|\.)|id_rsa|id_ed25519|.*\.(pem|pfx|p12|key)$)') { $why = 'CREDENTIAL_FILE' }
            elseif (-not $item.PSIsContainer -and $item.Name -match '(?i)\.(exe|dll|pyd|pyc|pyo|whl|msi|msix|zip|7z|tar|gz|log|dmp|iso|mp4|webm)$') { $why = 'BINARY_DEPENDENCY_ARCHIVE_OR_LOG' }
            elseif (-not $item.PSIsContainer -and $item.Name -match '(?i)^historical_replay_input_cache.*\.(sqlite3?|db)(-wal|-shm|-journal)?$') { $why = 'REGENERABLE_REPLAY_INPUT_CACHE' }
            if ($why) { [void]$Excluded.Add([ordered]@{path="$Label/$($relative.Replace('\','/'))"; reason=$why}); continue }
            if ($item.PSIsContainer) { $pending.Push($item.FullName); continue }
            [pscustomobject]@{source=$item.FullName; relative="$Label/$($relative.Replace('\','/'))"; length=$item.Length; ticks=$item.LastWriteTimeUtc.Ticks}
        }
    }
}
function Initialize-SreSqlite {
    if ('SreGateASnapshotSqlite' -as [type]) { return }
    Add-Type -TypeDefinition @'
using System;
using System.IO;
using System.Text;
using System.Runtime.InteropServices;
using System.Threading;
public static class SreGateASnapshotSqlite {
    const string Dll = "winsqlite3.dll";
    [DllImport(Dll, CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_open_v2(byte[] p, out IntPtr db, int flags, IntPtr vfs);
    [DllImport(Dll, CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_close_v2(IntPtr db);
    [DllImport(Dll, CallingConvention=CallingConvention.Cdecl)] static extern IntPtr sqlite3_errmsg(IntPtr db);
    [DllImport(Dll, CallingConvention=CallingConvention.Cdecl)] static extern IntPtr sqlite3_backup_init(IntPtr dst, byte[] dn, IntPtr src, byte[] sn);
    [DllImport(Dll, CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_backup_step(IntPtr b, int n);
    [DllImport(Dll, CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_backup_finish(IntPtr b);
    [DllImport(Dll, CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_prepare_v2(IntPtr db, byte[] sql, int n, out IntPtr st, IntPtr tail);
    [DllImport(Dll, CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_step(IntPtr st);
    [DllImport(Dll, CallingConvention=CallingConvention.Cdecl)] static extern IntPtr sqlite3_column_text(IntPtr st, int col);
    [DllImport(Dll, CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_finalize(IntPtr st);
    static byte[] Utf8(string s) { return Encoding.UTF8.GetBytes(s + "\0"); }
    static string Text(IntPtr p) {
        if(p == IntPtr.Zero) return "";
        int n=0; while(Marshal.ReadByte(p,n)!=0) n++;
        byte[] b=new byte[n]; Marshal.Copy(p,b,0,n); return Encoding.UTF8.GetString(b);
    }
    static void Check(int rc, IntPtr db, string stage) { if(rc!=0) throw new IOException(stage+": SQLite "+rc+" "+Text(sqlite3_errmsg(db))); }
    public static string Query(string path, string sql) {
        IntPtr db=IntPtr.Zero, st=IntPtr.Zero;
        try {
            Check(sqlite3_open_v2(Utf8(path),out db,1,IntPtr.Zero),db,"open snapshot read-only");
            Check(sqlite3_prepare_v2(db,Utf8(sql),-1,out st,IntPtr.Zero),db,"prepare verification");
            StringBuilder result=new StringBuilder(); int rc;
            while((rc=sqlite3_step(st))==100) { if(result.Length>0) result.Append("\n"); result.Append(Text(sqlite3_column_text(st,0))); }
            if(rc!=101) Check(rc,db,"verify snapshot"); return result.ToString();
        } finally { if(st!=IntPtr.Zero) sqlite3_finalize(st); if(db!=IntPtr.Zero) sqlite3_close_v2(db); }
    }
    public static void BackupCopy(string capturedSource, string destination) {
        IntPtr src=IntPtr.Zero,dst=IntPtr.Zero,b=IntPtr.Zero;
        try {
            // READWRITE is deliberate: recovery/checkpoint may touch this PRIVATE COPY.
            Check(sqlite3_open_v2(Utf8(capturedSource),out src,2,IntPtr.Zero),src,"open captured DB");
            Check(sqlite3_open_v2(Utf8(destination),out dst,6,IntPtr.Zero),dst,"create backup");
            b=sqlite3_backup_init(dst,Utf8("main"),src,Utf8("main"));
            if(b==IntPtr.Zero) throw new IOException("SQLite backup_init: "+Text(sqlite3_errmsg(dst)));
            var clock=System.Diagnostics.Stopwatch.StartNew(); int rc;
            do { rc=sqlite3_backup_step(b,256); if(rc==5||rc==6) Thread.Sleep(50);
                 if(clock.Elapsed.TotalMinutes>10) throw new IOException("SQLite copy backup timed out");
            } while(rc==0||rc==5||rc==6);
            if(rc!=101) Check(rc,dst,"backup step");
            IntPtr finished=b; b=IntPtr.Zero; Check(sqlite3_backup_finish(finished),dst,"backup finish");
        } finally { if(b!=IntPtr.Zero) sqlite3_backup_finish(b); if(dst!=IntPtr.Zero) sqlite3_close_v2(dst); if(src!=IntPtr.Zero) sqlite3_close_v2(src); }
        if(Query(destination,"PRAGMA integrity_check")!="ok") throw new IOException("Snapshot integrity_check failed: "+destination);
    }
}
'@
}
function Copy-SreLockedStream($Stream, [string]$Destination) {
    [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($Destination)) | Out-Null
    $outStream = [IO.File]::Open($Destination, 'CreateNew', 'Write', 'None')
    try { $Stream.Position=0; $Stream.CopyTo($outStream) } finally { $outStream.Dispose() }
}
function Protect-SreJson([string]$Path) {
    # Only configuration JSON is redacted. Original source hashes are retained.
    $text = [IO.File]::ReadAllText($Path)
    if ($text -notmatch '(?i)"(api[_-]?key|access[_-]?token|refresh[_-]?token|client[_-]?secret|password|secret[_-]?key|authorization)"\s*:') { return $false }
    $obj = $text | ConvertFrom-Json -ErrorAction Stop
    $changed = [ref]$false
    function Clear-SreSecret($Value, $Changed) {
        if ($null -eq $Value -or $Value -is [string] -or $Value.GetType().IsPrimitive) { return }
        if ($Value -is [Collections.IEnumerable] -and $Value -isnot [pscustomobject]) {
            foreach ($v in $Value) { Clear-SreSecret $v $Changed }; return
        }
        foreach ($prop in @($Value.PSObject.Properties)) {
            if ($prop.Name -match '^(?i:api[_-]?key|access[_-]?token|refresh[_-]?token|client[_-]?secret|password|secret[_-]?key|authorization)$') {
                if ($null -ne $prop.Value -and [string]$prop.Value -ne '') { $prop.Value='[REDACTED]'; $Changed.Value=$true }
            } else { Clear-SreSecret $prop.Value $Changed }
        }
    }
    Clear-SreSecret $obj $changed
    if ($changed.Value) { [IO.File]::WriteAllText($Path, ($obj | ConvertTo-Json -Depth 100), (New-Object Text.UTF8Encoding($false))) }
    return $changed.Value
}

function Invoke-SreContinuityEvidence([string]$PayloadRoot,[string]$OriginalEngine) {
    $inventory = New-Object Collections.ArrayList
    foreach ($runtimeName in @('.replay-v10-deps','.replay-v10-final-deps')) {
        $runtimeRoot=Join-Path $OriginalEngine $runtimeName
        if (Test-Path -LiteralPath $runtimeRoot) {
            foreach ($folder in Get-ChildItem -LiteralPath $runtimeRoot -Directory -Filter '*.dist-info') {
                $metadata=Join-Path $folder.FullName 'METADATA'
                if(Test-Path -LiteralPath $metadata) {
                    $lines=Get-Content -LiteralPath $metadata
                    [void]$inventory.Add([ordered]@{runtime=$runtimeName; distribution=$folder.Name; name=@($lines|Where-Object{$_ -match '^Name: '}|ForEach-Object{[string]$_}); version=@($lines|Where-Object{$_ -match '^Version: '}|ForEach-Object{[string]$_}); metadata_sha256=Get-SreHash $metadata})
                }
            }
        }
    }
    [IO.File]::WriteAllText((Join-Path $PayloadRoot 'environment-inventory.json'),(@{packages=@($inventory);powershell=$PSVersionTable.PSVersion.ToString();os=[Environment]::OSVersion.VersionString;architecture=$env:PROCESSOR_ARCHITECTURE;python_launcher=(Get-Command py.exe -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Source)} | ConvertTo-Json -Depth 8),(New-Object Text.UTF8Encoding($false)))
    $python=Get-Command py.exe -ErrorAction SilentlyContinue; $pyArgs=@('-3')
    if(-not $python){$python=Get-Command python.exe -ErrorAction SilentlyContinue; $pyArgs=@()}
    if(-not $python){throw 'Existing Python unavailable. No software installed; no accepted Gate B/C evidence ZIP produced.'}
    $program=@'
"""Embedded by build_collector.py. Standard library only; no app imports."""
from pathlib import Path
from urllib.request import Request,build_opener,HTTPRedirectHandler
from urllib.parse import urlsplit
import json,hashlib,sys,base64,concurrent.futures,threading,datetime
REQUESTS_B64='W10='
MANIFEST_B64=''
MAX_FILE=8*1024*1024;MAX_TOTAL=192*1024*1024
def allowed(url):
 try:
  u=urlsplit(url)
  return u.scheme=='https'and u.hostname=='nsearchives.nseindia.com'and not u.username and not u.password and u.port in (None,443)and any(u.path.startswith(p)for p in ['/corporate/','/content/cm/','/content/indices/','/content/circulars/'])
 except ValueError:return False
class NoRedirect(HTTPRedirectHandler):
 def redirect_request(self,*args,**kwargs):raise ValueError('REDIRECT_REFUSED')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def inspect_contract(root):
 m=json.loads(base64.b64decode(MANIFEST_B64));rows=[]
 for n,v in m['files'].items():
  p=root/'engine'/n;actual=sha(p)if p.is_file()else None
  rows.append({'file':n,'sha256':actual,'state':'LATEST_CANDIDATE_MATCH'if actual==v['new_sha256']else 'PRIOR_CAPTURE_MATCH'if actual==v['old_sha256']else 'MISSING_OR_DIFFERENT_CURRENT_SOURCE'})
 guards=[n for n,h in m['guard_files'].items()if not(root/'engine'/n).is_file()or sha(root/'engine'/n)!=h]
 expected=set(m['guard_files'])|set(m['files'])
 extra=[p.relative_to(root/'engine').as_posix()for folder in ['stock_app','modern_ui']for p in (root/'engine'/folder).glob('*.py')if p.relative_to(root/'engine').as_posix()not in expected]
 guards+=['UNRECOGNIZED_MODULE:'+n for n in extra]
 return {'files':rows,'guard_mismatches':guards,'status':'LATEST_PATCH_SOURCE_MATCH'if not guards and all(r['state']=='LATEST_CANDIDATE_MATCH'for r in rows)else 'PRIOR_BASELINE_MATCH'if not guards and all(r['state']=='PRIOR_CAPTURE_MATCH'for r in rows)else 'CURRENT_SOURCE_REQUIRES_DELTA_REVIEW','note':'No source was overwritten and no patch was applied.'}
def main():
 root=Path(sys.argv[1]);skip=len(sys.argv)>2 and sys.argv[2]=='SKIP_NETWORK';out=root/'continuity-evidence';out.mkdir();(out/'installed-contract.json').write_text(json.dumps(inspect_contract(root),indent=2))
 requests=json.loads(base64.b64decode(REQUESTS_B64));total=0;lock=threading.Lock();records=[]
 def retrieve(r):
  nonlocal total
  rec=dict(r)
  if skip:return {**rec,'status':'SKIPPED_BY_EXPLICIT_OFFLINE_OPTION'}
  if not allowed(r['url']):return {**rec,'status':'BLOCKED_NOT_OFFICIAL_ALLOWLIST'}
  try:
   with build_opener(NoRedirect()).open(Request(r['url'],headers={'User-Agent':'Mozilla/5.0','Accept':'application/xml,text/xml,text/csv,application/zip,*/*'}),timeout=12)as response:
    if not allowed(response.url):raise ValueError('RESPONSE_URL_OUTSIDE_ALLOWLIST')
    data=response.read(MAX_FILE+1)
    if len(data)>MAX_FILE:return {**rec,'status':'PER_FILE_LIMIT'}
   actual=hashlib.sha256(data).hexdigest()
   with lock:
    if total+len(data)>MAX_TOTAL:return {**rec,'status':'TOTAL_LIMIT'}
    total+=len(data)
   path=out/'official-downloads'/r['filename'];path.parent.mkdir(exist_ok=True);path.write_bytes(data)
   expected=r.get('expected_sha256');status='EXACT_REQUESTED_HASH_MATCH'if expected and actual==expected else 'HASH_MISMATCH_REVIEW_REQUIRED'if expected else 'CAPTURED_UNVALIDATED_ORIGINAL'
   return {**rec,'status':status,'sha256':actual,'bytes':len(data),'path':path.relative_to(root).as_posix()}
  except Exception as e:return {**rec,'status':'FETCH_FAILED','error_type':type(e).__name__,'detail':str(e)[:250]}
 with concurrent.futures.ThreadPoolExecutor(max_workers=4)as pool:
  for rec in pool.map(retrieve,requests):
   records.append(rec)
   if len(records)%25==0:print('Official evidence requests processed:',len(records),'/',len(requests),flush=True)
 report={'python_version':sys.version,'python_executable':sys.executable,'created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'requested':len(requests),'bytes_saved':total,'records':records,'source_application_files_written':False,'network_mode':'EXPLICIT_OFFLINE'if skip else 'OFFICIAL_NSE_ONLY','status':'CAPTURE_COMPLETE_WITH_PER_REQUEST_RESULTS','all_results_are_evidence_only':True,'financial_ingestion_performed':False}
 (out/'official-evidence-report.json').write_text(json.dumps(report,indent=2));print('Official evidence saved:',sum('path'in r for r in records),'of',len(records),flush=True)
"""Read-only analysis of private snapshot copies. No app context, network or trades."""
from pathlib import Path
from types import SimpleNamespace
import json,hashlib,zlib,csv,sys,datetime,importlib.metadata as metadata
MAX_JSON=64*1024*1024

def digest(v):return hashlib.sha256(json.dumps(v,sort_keys=True,separators=(',',':'),allow_nan=False,default=str).encode()).hexdigest()
def file_hash(p):
 h=hashlib.sha256()
 with Path(p).open('rb')as f:
  for b in iter(lambda:f.read(1048576),b''):h.update(b)
 return h.hexdigest()
def unpack(p):
 d=zlib.decompressobj();raw=d.decompress(p.read_bytes(),MAX_JSON+1)
 if len(raw)>MAX_JSON or d.unconsumed_tail or not d.eof or d.unused_data:raise ValueError('BOUNDED_ZLIB_VALIDATION_FAILED')
 return json.loads(raw)
def inspect_replays(root):
 records=[];errors=[]
 for p in sorted((root/'application-state/historical_replay_checkpoints_v2').glob('*.complete.zlib')):
  base={'file':p.relative_to(root).as_posix(),'file_sha256':file_hash(p),'bytes':p.stat().st_size}
  try:
   obj=unpack(p);r=obj['value'];proof=r.get('v10_acceptance')or{};c=proof.get('contract')or{};config=c.get('config')or{};coverage=r.get('coverage')or[]
   wrapper=obj.get('schema')=='SRE_REPLAY_CHECKPOINT_V2'and obj.get('key')==p.name.split('.')[0]
   payload={k:v for k,v in r.items()if k not in ('v10_acceptance','replay_cache_status','replay_request_stats','replay_input_cache_stats')}
   proof_ok=bool(proof)and proof.get('key')==digest(c)and proof.get('payload_sha256')==digest(payload)
   sessions=c.get('sessions')or[x.get('date')for x in coverage];span=r.get('requested_range')or{}
   records.append({**base,'wrapper_valid':wrapper,'attestation_present':bool(proof),'self_integrity_match':proof_ok,'historical_flag':r.get('pit_completeness'),'period':r.get('requested_period'),'range':span,'original_sessions':sessions,'replayed_sessions':r.get('sessions_replayed'),'source_fingerprint':r.get('replay_fundamental_source_fingerprint'),'market_fingerprint':r.get('replay_market_content_signature'),'context_fingerprint':r.get('replay_context_signature'),'runtime':c.get('runtime'),'config':config,'execution_assumptions':r.get('execution_assumptions'),'metrics':r.get('metrics'),'old_contract':c,'current_validation_status':'NOT_REVALIDATED; old COMPLETE flag alone is insufficient'})
  except Exception as e:errors.append({**base,'error':type(e).__name__+': '+str(e)[:250]})
 return {'records':records,'errors':errors,'complete_files':len(records)+len(errors),'attested_self_integrity_matches':sum(x['self_integrity_match']for x in records),'distinct_historically_complete_single_sessions':sorted({x['range'].get('start')for x in records if x['historical_flag']=='COMPLETE'and x['range'].get('start')and x['range'].get('start')==x['range'].get('end')}),'never_current_validated_by_this_inventory':True}

def native_fingerprints(original,manifest):
 # Import only hash-verified pure replay/feature modules, never ModernAppContext.
 # No class instances/cache construction. Prevent bytecode writes into originals.
 sys.dont_write_bytecode=True
 expected={**manifest['guard_files'],**{n:v['new_sha256']for n,v in manifest['files'].items()if n.endswith(('.py','.js','.json','.html','.css'))}}
 known={n:h for n,h in expected.items()if n.endswith('.py')and n.startswith(('stock_app/','modern_ui/'))}
 unknown=[p.relative_to(original).as_posix()for d in ['stock_app','modern_ui']for p in(original/d).glob('*.py')if p.relative_to(original).as_posix()not in known]
 bad=[n for n,h in known.items()if not(original/n).is_file()or file_hash(original/n)!=h]
 if bad or unknown:return {'status':'BLOCKED_UNRECOGNIZED_SOURCE','mismatches':bad,'unknown_modules':unknown}
 sys.path.insert(0,str(original))
 try:
  from stock_app.replay_v10 import source_signature,market_signature,RUNTIME
  source=source_signature(original,original)
  candidates=[]
  for parent in [original/'data/normalized/nse_official',original/'data/market_data']:
   if parent.is_dir():
    for folder in sorted({p.parent for p in parent.rglob('*.csv')}):
     candidates.append({'root':str(folder),'fingerprint':market_signature(SimpleNamespace(cache_roots=[folder]))})
  return {'status':'VERIFIED_PURE_MODULE_FINGERPRINTS','source_fingerprint':source,'runtime':RUNTIME,'market_root_candidates':candidates,'active_market_root_and_context_status':'Determine actual configured root/context from returned source/config; no app context was instantiated','originals_written':False}
 except Exception as e:return {'status':'BLOCKED_EXISTING_RUNTIME_IMPORT','error':type(e).__name__+': '+str(e)[:250]}

def audit_capture(root,original,manifest,compute_native=True):
 root=Path(root);original=Path(original);out=root/'gatebc-evidence';out.mkdir()
 inventory=inspect_replays(root);(out/'REPLAYS.json').write_text(json.dumps(inventory,indent=2))
 with(out/'REPLAYS.csv').open('w',newline='')as f:
  fields=['file','file_sha256','historical_flag','period','range','original_sessions','attestation_present','self_integrity_match','source_fingerprint','market_fingerprint','context_fingerprint']
  w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows({k:json.dumps(r.get(k))if isinstance(r.get(k),(dict,list))else r.get(k)for k in fields}for r in inventory['records'])
 deltas=[]
 for n,v in manifest['files'].items():
  p=root/'engine'/n;actual=file_hash(p)if p.is_file()else None
  deltas.append({'file':n,'pre_correction_sha256':v['old_sha256'],'correction_sha256':v['new_sha256'],'captured_sha256':actual,'correction_match':actual==v['new_sha256'],'classification':'KNOWN_CORRECTION_EXACT'if actual==v['new_sha256']else'CURRENT_DIFF_REQUIRES_REVIEW'})
 (out/'CORRECTION_DEPENDENCIES.json').write_text(json.dumps(deltas,indent=2))
 fingerprints=native_fingerprints(original,manifest)if compute_native else{'status':'NOT_COMPUTED_IN_OFFLINE_FIXTURE'}
 for r in inventory['records']:
  r['source_matches_native']=r['source_fingerprint']==fingerprints.get('source_fingerprint')if fingerprints.get('source_fingerprint')else None
  r['matching_market_candidates']=[x['root']for x in fingerprints.get('market_root_candidates',[])if x['fingerprint']==r['market_fingerprint']]
  r['runtime_matches_native']=r.get('runtime')==fingerprints.get('runtime')if fingerprints.get('runtime')else None
 (out/'NATIVE_FINGERPRINTS.json').write_text(json.dumps(fingerprints,indent=2));(out/'REPLAYS.json').write_text(json.dumps(inventory,indent=2))
 # Copies are private; readonly immutable SQL inventory never opens live DBs.
 import sqlite3
 dbs=[]
 for p in (root/'application-state').glob('*.sqlite3'):
  with sqlite3.connect(p.resolve().as_uri()+'?mode=ro&immutable=1',uri=True)as c:
   ts=[x[0]for x in c.execute("select name from sqlite_master where type='table'")];dbs.append({'file':p.name,'tables':ts,'integrity':c.execute('pragma quick_check').fetchone()[0]})
 (out/'SQLITE_TABLES.json').write_text(json.dumps(dbs,indent=2))
 # Inventory binaries/versions/licenses only. Binary copies are deliberately not redistributed.
 binary=[];licenses=[];seen=set();count=0
 for p in original.rglob('*'):
  if not p.is_file()or any(x.startswith(('.oct31-','.gatea-','.replay-v10-backup','.replay-v10-final-backup'))for x in p.relative_to(original).parts):continue
  if p.suffix.lower()in('.exe','.dll','.pyd','.whl'):
   binary.append({'path':str(p),'bytes':p.stat().st_size,'sha256':file_hash(p)})
  if p.name.lower().startswith(('license','licence','copying','notice'))and p.stat().st_size<1024*1024:licenses.append({'path':str(p),'sha256':file_hash(p)})
 versions=[]
 for runtime in [original/'.replay-v10-deps',original/'.replay-v10-final-deps']:
  for d in metadata.distributions(path=[str(runtime)]):versions.append({'runtime':str(runtime),'name':d.metadata.get('Name'),'version':d.version})
 versions += [{'runtime':'collector_interpreter_visible_distribution','name':d.metadata.get('Name'),'version':d.version}for d in metadata.distributions()]
 (out/'RUNTIME_PORTABILITY.json').write_text(json.dumps({'python_executable':sys.executable,'python_version':sys.version,'binary_files':binary,'license_files':licenses,'distributions':versions,'binary_payload_included':False,'blocker':'Actual launcher/complete runtime binaries and redistribution permissions require separate verification; inventory is not portable-release acceptance'},indent=2))
 summary={'created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'snapshot_only':True,'no_replay_executed':True,'no_network':True,'no_app_context_or_api_called':True,'original_databases_opened_by_sqlite':False,'records_observed':inventory['complete_files'],'distinct_historically_complete_single_sessions':inventory['distinct_historically_complete_single_sessions'],'native_fingerprint_status':fingerprints['status'],'gate_b_recovery':'BLOCKED_PENDING_CURRENT_CAPTURE_REVIEW_AND_GUARDED_THREE_SESSION_EXECUTION','gate_c':'BLOCKED_ACTUAL_MACHINE_ACCEPTANCE_NOT_EXECUTED'}
 (out/'SUMMARY.json').write_text(json.dumps(summary,indent=2));return summary

if __name__=='__main__':
 main()
 report=audit_capture(Path(sys.argv[1]),Path(sys.argv[3]),json.loads(base64.b64decode(MANIFEST_B64)))
 print('Gate B/C evidence inventory:',json.dumps(report),flush=True)

'@
    $mode='SKIP_NETWORK'
    Write-Host 'Source capture finished. Inventorying replay dependencies and runtime; no downloads or replay.'
    $program | & $python.Source @pyArgs '-' $PayloadRoot $mode $OriginalEngine
    if($LASTEXITCODE -ne 0){throw 'Gate B/C evidence helper failed. Originals unchanged; no accepted ZIP produced.'}
}

function New-SreGateASnapshot([string]$DataRoot, [string]$InstallRoot, [string]$OutputRoot) {
    if ($env:OS -ne 'Windows_NT') { throw 'Run this collector on the Windows computer with SRE installed.' }
    $DataRoot = [IO.Path]::GetFullPath($DataRoot).TrimEnd('\','/')
    if (-not $InstallRoot) { $InstallRoot = Join-Path $DataRoot 'native-engine-0.14.13' }
    $InstallRoot = [IO.Path]::GetFullPath($InstallRoot).TrimEnd('\','/')
    if (-not (Test-Path -LiteralPath (Join-Path $InstallRoot 'modern_ui\api.py') -PathType Leaf) -or
        -not (Test-Path -LiteralPath (Join-Path $InstallRoot 'stock_app\live_decision_v1.py') -PathType Leaf)) { throw "Expected installed SRE source not found: $InstallRoot" }
    if (-not $OutputRoot) { $OutputRoot = [Environment]::GetFolderPath('Desktop'); if (-not $OutputRoot) { $OutputRoot = Join-Path $env:USERPROFILE 'Downloads' } }
    $OutputRoot = [IO.Path]::GetFullPath($OutputRoot)
    if ((Test-SreInside $OutputRoot $DataRoot) -or (Test-SreInside $OutputRoot $InstallRoot)) { throw 'Snapshot output must be outside the SRE installation and application-data directories.' }
    Assert-SreStopped $DataRoot $InstallRoot
    Initialize-SreSqlite
    $excluded = New-Object Collections.ArrayList
    $files = @(Get-SreFiles $InstallRoot 'engine' '' $excluded) + @(Get-SreFiles $DataRoot 'application-state' $InstallRoot $excluded)
    $fileByRelative = @{}; foreach ($f in $files) { $fileByRelative[$f.relative]=$f }
    if ($files.Count -eq 0) { throw 'No source files found.' }
    $dbs = @($files | Where-Object { Test-SreSqliteFile $_.source })
    $dbPaths = @{}; $sidecarPaths = @{}
    foreach ($db in $dbs) {
        $dbPaths[$db.source]=$true
        foreach ($suffix in @('-wal','-shm','-journal')) { $sidecarPaths[$db.source+$suffix]=$true }
    }
    foreach ($required in @('stock_recommendation_engine.sqlite3','phase81_validation.sqlite3')) {
        if (-not @($dbs | Where-Object { [IO.Path]::GetFileName($_.source) -eq $required }).Count) { throw "Required active database not found: $required. No partial snapshot will be accepted." }
    }
    $bytes = ($files | Measure-Object -Property length -Sum).Sum
    $drive = New-Object IO.DriveInfo([IO.Path]::GetPathRoot($OutputRoot))
    $needed = 3 * $bytes + 512MB
    if ($drive.AvailableFreeSpace -lt $needed) { throw ('Insufficient free space: need approximately {0:N2} GB for capture, DB normalization and verified ZIP.' -f ($needed/1GB)) }
    [IO.Directory]::CreateDirectory($OutputRoot) | Out-Null
    $name = 'SRE-GateBC-ReadOnly-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [Guid]::NewGuid().ToString('N').Substring(0,6)
    $work = Join-Path $OutputRoot ($name + '-working')
    $capture = Join-Path $work 'raw-private-copy'
    $payload = Join-Path $work 'snapshot'
    $zip = Join-Path $OutputRoot ($name + '.zip')
    $partialZip = Join-Path $work 'unverified.zip'
    $locks = @{}
    $records = New-Object Collections.ArrayList
    $recordByRelative = @{}
    $databaseRecords = New-Object Collections.ArrayList
    $finished = $false
    try {
        [IO.Directory]::CreateDirectory($capture) | Out-Null
        [IO.Directory]::CreateDirectory($payload) | Out-Null
        # Lock ALL selected DBs and sidecars together before copying ANY data.
        foreach ($f in $files) {
            if ($dbPaths.ContainsKey($f.source) -or $sidecarPaths.ContainsKey($f.source)) {
                try { $locks[$f.source] = [IO.File]::Open($f.source, 'Open', 'Read', 'Read') }
                catch { throw "Database is in use or unreadable: $($f.relative). Close SRE and rerun. $($_.Exception.Message)" }
            }
        }
        Assert-SreStopped $DataRoot $InstallRoot
        Write-Host ('Capturing {0} files ({1:N1} MB); {2} databases. Keep SRE closed.' -f $files.Count,($bytes/1MB),$dbs.Count)
        foreach ($f in $files) {
            $hash = Get-SreHash $f.source
            $dest = Join-Path $capture $f.relative
            if ($locks.ContainsKey($f.source)) { Copy-SreLockedStream $locks[$f.source] $dest }
            else { [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($dest)) | Out-Null; [IO.File]::Copy($f.source,$dest,$false) }
            if ((Get-SreHash $dest) -ne $hash -or (Get-SreHash $f.source) -ne $hash) { throw "Source changed during capture: $($f.relative). Close SRE and rerun." }
            $r = [ordered]@{path=$f.relative; source_sha256=$hash; source_bytes=$f.length; captured_sha256=$hash; transformed=$false; archive_included=$true}
            [void]$records.Add($r); $recordByRelative[$f.relative]=$r
        }
        $allAfter = @(Get-SreFiles $InstallRoot 'engine' '' (New-Object Collections.ArrayList)) + @(Get-SreFiles $DataRoot 'application-state' $InstallRoot (New-Object Collections.ArrayList))
        if ((@($allAfter.relative | Sort-Object) -join "`n") -cne (@($files.relative | Sort-Object) -join "`n")) { throw 'Source inventory changed during capture. Keep SRE closed and rerun.' }
        foreach ($r in $records) {
            $f = $fileByRelative[$r.path]
            if ((Get-SreHash $f.source) -ne $r.source_sha256) { throw "Source changed before snapshot completion: $($r.path)" }
        }
        Assert-SreStopped $DataRoot $InstallRoot
        # All originals remain read-locked until the complete capture is verified.
        foreach ($handle in $locks.Values) { $handle.Dispose() }; $locks.Clear()
        foreach ($f in $files) {
            if ($sidecarPaths.ContainsKey($f.source)) { $recordByRelative[$f.relative].archive_included=$false; continue }
            $src = Join-Path $capture $f.relative
            $dest = Join-Path $payload $f.relative
            [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($dest)) | Out-Null
            $record = $recordByRelative[$f.relative]
            if ($dbPaths.ContainsKey($f.source)) {
                [SreGateASnapshotSqlite]::BackupCopy($src,$dest)
                $record.transformed=$true
                [void]$databaseRecords.Add([ordered]@{path=$f.relative; integrity_check='ok'; sqlite_backup='WINDOWS_SQLITE_BACKUP_FROM_PRIVATE_DB_AND_SIDECARS'; tables=[SreGateASnapshotSqlite]::Query($dest,"SELECT name FROM sqlite_master WHERE type='table' ORDER BY name")})
            } else {
                [IO.File]::Copy($src,$dest,$false)
                if ([IO.Path]::GetExtension($dest) -eq '.json' -and (Protect-SreJson $dest)) { $record.transformed=$true; $record['redacted_secret_values']=$true }
            }
            $record.captured_sha256=Get-SreHash $dest
        }
        Invoke-SreContinuityEvidence $payload $InstallRoot
        # Sidecars are deliberately absent from the final ZIP: each normalized DB
        # contains their committed state. Preserve their original hashes as evidence.
        $manifest = [ordered]@{
            schema='SRE_GATEBC_READONLY_CAPTURE_V1'; created_utc=[DateTime]::UtcNow.ToString('o')
            source_engine=$InstallRoot; source_application_data=$DataRoot
            powershell=$PSVersionTable.PSVersion.ToString(); platform=[Environment]::OSVersion.VersionString
            original_databases_opened_by_sqlite=$false; original_files_written=$false
            stopped_process_checks='PASS'; stable_source_inventory_and_hashes='PASS'
            source_files=@($records); databases=@($databaseRecords); exclusions=@($excluded)
            notes=@('Source paths and source hashes describe originals; captured hashes describe normalized or redacted files.','Do not interpret a backup hash change as a changed portfolio. Compare table contents.','Replay feature/input caches and dependencies excluded; official price/fundamental and entry evidence retained unless explicitly listed in exclusions.','Source Scripts folders are retained. Private binary runtimes excluded but distribution metadata recorded. Network disabled. Replay records/checkpoints and correction backups retained. Binaries inventoried, never copied.','Snapshots contain private financial portfolio data. Upload privately to the Work task; do not publish to GitHub.')
        }
        [IO.File]::WriteAllText((Join-Path $payload 'snapshot-manifest.json'),($manifest | ConvertTo-Json -Depth 12),(New-Object Text.UTF8Encoding($false)))
        # Release-time collector and instructions are embedded for reproducibility.
        if ($script:CollectorPath -and (Test-Path -LiteralPath $script:CollectorPath)) { [IO.File]::Copy($script:CollectorPath,(Join-Path $payload 'COLLECTOR.ps1'),$false) }
        $checksums = @{}
        foreach ($f in Get-ChildItem -LiteralPath $payload -Recurse -File -Force) { $rel=$f.FullName.Substring($payload.Length+1).Replace('\','/'); $checksums[$rel]=Get-SreHash $f.FullName }
        $checksumLines=@($checksums.Keys | Sort-Object | ForEach-Object { $checksums[$_]+'  '+$_ })
        $checksumPath=Join-Path $payload 'CAPTURE_CHECKSUMS.sha256'
        [IO.File]::WriteAllLines($checksumPath,$checksumLines,(New-Object Text.UTF8Encoding($false)))
        $checksums['CAPTURE_CHECKSUMS.sha256']=Get-SreHash $checksumPath
        Add-Type -AssemblyName System.IO.Compression
        Add-Type -AssemblyName System.IO.Compression.FileSystem
        # .NET Framework's CreateFromDirectory uses backslashes in ZIP names.
        # Create explicit forward-slash entries for portable Work/Linux extraction.
        $writer=[IO.Compression.ZipFile]::Open($partialZip,[IO.Compression.ZipArchiveMode]::Create)
        try {
            foreach ($rel in $checksums.Keys) {
                [IO.Compression.ZipFileExtensions]::CreateEntryFromFile($writer,(Join-Path $payload $rel),$rel,[IO.Compression.CompressionLevel]::Optimal) | Out-Null
            }
        } finally { $writer.Dispose() }
        $archive = [IO.Compression.ZipFile]::OpenRead($partialZip)
        $seen = @{}
        try {
            foreach ($entry in $archive.Entries) {
                if ($entry.FullName.EndsWith('/')) { continue }
                if ($seen.ContainsKey($entry.FullName) -or -not $checksums.ContainsKey($entry.FullName)) { throw "Unexpected/duplicate archive entry: $($entry.FullName)" }
                $stream=$entry.Open(); $sha=[Security.Cryptography.SHA256]::Create()
                try { $actual=([BitConverter]::ToString($sha.ComputeHash($stream))).Replace('-','').ToLowerInvariant() } finally { $sha.Dispose(); $stream.Dispose() }
                if ($actual -ne $checksums[$entry.FullName]) { throw "Archive integrity failure: $($entry.FullName)" }
                $seen[$entry.FullName]=$true
            }
            if ($seen.Count -ne $checksums.Count) { throw 'Archive is missing captured files.' }
        } finally { $archive.Dispose() }
        [IO.File]::Move($partialZip,$zip)
        $zipHash=Get-SreHash $zip
        $finished=$true
        Write-Host ''
        Write-Host 'SUCCESS: consistent snapshot captured and every ZIP entry SHA-256 verified.' -ForegroundColor Green
        Write-Host "UPLOAD THIS ONE FILE: $zip"
        Write-Host "ZIP SHA-256: $zipHash"
        return [pscustomobject]@{zip=$zip; sha256=$zipHash; files=$seen.Count; databases=$dbs.Count}
    } finally {
        foreach ($handle in $locks.Values) { $handle.Dispose() }
        if (Test-Path -LiteralPath $work) { Remove-Item -LiteralPath $work -Recurse -Force -ErrorAction SilentlyContinue }
        if (-not $finished -and (Test-Path -LiteralPath $zip)) { Remove-Item -LiteralPath $zip -Force -ErrorAction SilentlyContinue }
        if (-not $finished) { Write-Warning 'Snapshot failed safely. No accepted ZIP was produced. Installation and database originals were not written.' }
    }
}
$script:CollectorPath = $PSCommandPath
if ($MyInvocation.InvocationName -ne '.') {
    try { New-SreGateASnapshot $AppDataRoot $EngineRoot $OutputDirectory | Out-Null }
    catch { Write-Error $_; exit 1 }
}
